export function parseRange(text) {
  const [from, to] = text.split("-");
  return { from: Number(from), to: Number(to) };
}

input.replace:
export function parseRange(text) {
  const [from, to] = text.split("-");
  return { from: Number(from), to: to === undefined ? Number(from) : Number(to) };
}
